class Demo {
    static <T extends Number & Comparable<T>> T largest(T a, T b) {
        return a.compareTo(b) >= 0 ? a : b;
    }
    public static void main(String[] args) throws ReflectiveOperationException {
        System.out.println(Demo.class.getDeclaredMethod(
                "largest", Number.class, Number.class).getReturnType().getSimpleName());
        System.out.println(largest(2.0, 1.0));
    }
}

