import java.util.ArrayList;
import java.util.List;

class Demo {
    static <T> void append(List<? extends T> source, List<? super T> destination) {
        for (T item : source) {
            destination.add(item);
        }
    }
    public static void main(String[] args) {
        List<Number> output = new ArrayList<>();
        append(List.of(1, 2), output);
        System.out.println(output);
    }
}

import java.util.ArrayList;
import java.util.List;

class Demo {
    static void swapFirstPair(List<?> items) { swap(items); }
    static <T> void swap(List<T> items) {
        T first = items.get(0);
        items.set(0, items.get(1));
        items.set(1, first);
    }
    public static void main(String[] args) {
        List<String> values = new ArrayList<>(List.of("a", "b"));
        swapFirstPair(values);
        System.out.println(values);
    }
}

